const input1 = document.getElementById("userInput1");
const donebtn = document.querySelector(".done-btn");
var flag = 0;
input1.value = 10;
donebtn.addEventListener("click", function(){
    if(flag == 0){
        bmi();
    }else{
        init();
    }

});
function init(){
    //show and enable the done button
    input1.value = 10;
    donebtn.innerHTML = "Done";
    flag = 0;
    // enable number input
    input1.disabled = false;
    var iff = document.getElementById("iff");
    var ob = document.getElementById("ob");
    var elsifov = document.getElementById("elsifov");
    var ov = document.getElementById("ov");
    var elsifhw = document.getElementById("elsifhw");
    var hw = document.getElementById("hw");
    var els = document.getElementById("els");
    var un = document.getElementById("un");
    var out = document.getElementById("output");
    iff.style.background = "#F8F8F8";
    ob.style.background = "#F8F8F8";
    elsifov.style.background = "#F8F8F8";
    ov.style.background = "#F8F8F8";
    elsifhw.style.background = "#F8F8F8";
    hw.style.background = "#F8F8F8";
    els.style.background = "#F8F8F8";
    un.style.background = "#F8F8F8";
    input1.style.background = "#CCCCCC";
    out.innerHTML = "Output: ";
}
function bmi(){
    //disable the done button and hide it
    console.log("entered");
    donebtn.disabled = true;
    donebtn.style.visibility = "hidden";
    input1.disabled = true;
    var iff = document.getElementById("iff");
    var ob = document.getElementById("ob");
    var elsifov = document.getElementById("elsifov");
    var ov = document.getElementById("ov");
    var elsifhw = document.getElementById("elsifhw");
    var hw = document.getElementById("hw");
    var els = document.getElementById("els");
    var un = document.getElementById("un");
    var out = document.getElementById("output");
    var t = input1.value;
    if(isNaN(parseFloat(t)) || parseFloat(t) < 0 || parseFloat(t) > 100) {
        //console.log("Invalid input");
        input1.style.background = "red";
        donebtn.innerHTML = "Reset";
        flag = 1;
        donebtn.disabled = false;
        donebtn.style.visibility = "visible";
    }else{
        setTimeout(function(){
            iff.style.background = "#FFCC00";
        },1000)
        setTimeout(function(){
            if(parseFloat(t) >= 30.0){
                ob.style.background = "#FFCC00";
            }else{
                elsifov.style.background = "#FFCC00";
            }
        },2000)
        setTimeout(function(){
            if(parseFloat(t) >= 30.0){
                out.innerHTML = "Output: obese";
                donebtn.innerHTML = "Reset";
                donebtn.disabled = false;
                donebtn.style.visibility = "visible";
                flag = 1;
            }else if(parseFloat(t) >= 25.0){
                ov.style.background = "#FFCC00";
                setTimeout(function(){
                    out.innerHTML = "Output: overweight";
                    donebtn.innerHTML = "Reset";
                    donebtn.disabled = false;
                    donebtn.style.visibility = "visible";
                    flag = 1;
                },1000);
            }else if(parseFloat(t) >= 18.5){
                elsifhw.style.background = "#FFCC00";
                setTimeout(function(){
                    hw.style.background = "#FFCC00";
                },1000);
                setTimeout(function(){
                    out.innerHTML = "Output: healthy";
                    donebtn.innerHTML = "Reset";
                    donebtn.disabled = false;
                    donebtn.style.visibility = "visible";
                    flag = 1;
                },2000);  
            }else{
                elsifhw.style.background = "#FFCC00";
                setTimeout(function(){
                    un.style.background = "#FFCC00";
                },1000);
                setTimeout(function(){
                    out.innerHTML = "Output: underweight";
                    donebtn.innerHTML = "Reset";
                    donebtn.disabled = false;
                    donebtn.style.visibility = "visible";
                    flag = 1;
                },2000);
            }   
        },3000)
        }
}
